const wk = (t, mon) => { const d = new Date(t.slice(0, 10) + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() - (mon ? (d.getUTCDay() + 6) % 7 : d.getUTCDay())); return d.toISOString().slice(0, 10); };
