// assign.mjs — who works when, under POLICY.md.
//
// Shape: refuse early when a short necessary-condition proof exists (checkStretches), then a
// day-by-day backtracking search. Every rule is a hard constraint in every phase. The phases
// only differ in how tight the per-person targets are:
//   1. exact integer targets (floor of share, leftovers by a seeded lottery) — this is what makes
//      leftovers rotate between periods instead of always going to the same person;
//   2. weekends within ±1 of target; 3. totals ±1 as well; 4. the policy ranges themselves.
// Each phase gets several short searches with a seeded jitter on the order (restarts). The last
// phase ends with an unbounded-order search; if that one finishes, the refusal is a proof.
// No name or file order decides anything: ties are broken by a hash seeded by the start date.
import { days, isWeekend } from './calendar.mjs';
import { shares, bounds, MAX_RUN } from './policy.mjs';

export class RotaError extends Error {}

function hash(...xs) { // small deterministic integer hash → [0,1)
  let h = 2166136261;
  for (const x of xs) for (const c of String(x)) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); }
  h ^= h >>> 15; h = Math.imul(h, 2246822507); h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

// Integer targets summing to `sum`: floor of each share, the leftover units to people drawn by
// systematic sampling weighted by their fractional part, offset seeded by `seed`.
function lottery(values, sum, seed) {
  const fl = values.map((v) => Math.floor(v + 1e-9));
  let left = sum - fl.reduce((a, b) => a + b, 0);
  if (left <= 0) return fl;
  const fr = values.map((v, i) => Math.max(0, v - fl[i]));
  const order = values.map((_, i) => i).sort((a, b) => hash(seed, 'o', a) - hash(seed, 'o', b));
  const F = fr.reduce((a, b) => a + b, 0);
  const step = F / left;
  let next = hash(seed, 'u') * step, acc = 0;
  for (const i of order) {
    acc += fr[i];
    while (left > 0 && next < acc - 1e-12) { fl[i]++; left--; next += step; }
  }
  return fl;
}

// forced[i][d]: person i is on day d in every lawful rota — the only nurse not on leave, or one of
// only two people not on leave (rules 1 and 2).
export function forcedDays(people, ds) {
  const forced = people.map(() => new Array(ds.length).fill(false));
  ds.forEach((day, d) => {
    const free = [...people.keys()].filter((i) => !people[i].leave.has(day));
    const nurses = free.filter((i) => people[i].role === 'nurse');
    if (nurses.length === 1) forced[nurses[0]][d] = true;
    if (free.length === 2) for (const i of free) forced[i][d] = true;
  });
  return forced;
}

// Refusal proofs. For every stretch [a,b) of days, each person can work at most
// min(rule-4 cap, most possible inside under leave + rule 3) there, and must work at least
// (rule-4 floor − most possible outside the stretch). Same for weekends. The days need 2L shifts,
// L of them by nurses, and at most L by aides. Every bound is necessary, so a hit is a proof.
export function checkStretches(people, ds, bnd) {
  const n = ds.length, k = people.length;
  const wkd = ds.map(isWeekend);
  // most[i][a][b-a]: most days person i can work in [a,b) starting rested (greedy is optimal).
  const most = people.map((p) => {
    const rows = [];
    for (let a = 0; a <= n; a++) {
      const row = [0]; let c = 0, run = 0, wc = 0; const wrow = [0];
      for (let d = a; d < n; d++) {
        if (!p.leave.has(ds[d]) && run < MAX_RUN) { c++; run++; if (wkd[d]) wc++; } else run = 0;
        row.push(c); wrow.push(wc);
      }
      rows.push({ row, wrow });
    }
    return rows;
