  const wkPre = [0]; wkd.forEach((w, j) => wkPre.push(wkPre[j] + (w ? 1 : 0)));
  // Period-wide role totals for the coupled pass: the nurses can't work more than the sum of their
  // rule-4 caps in the whole period, and at least one of them works every day outside a stretch.
  const nurseHi = people.reduce((s, p, i) => s + (p.role === 'nurse' ? bnd[i].hi : 0), 0);
  const aideLo = people.reduce((s, p, i) => s + (p.role === 'nurse' ? 0 : bnd[i].lo), 0);
  const forced = forcedDays(people, ds);
  const fPre = forced.map((f) => { const s = [0]; f.forEach((x, j) => s.push(s[j] + (x ? 1 : 0))); return s; });
  const fWkPre = forced.map((f) => { const s = [0]; f.forEach((x, j) => s.push(s[j] + (x && wkd[j] ? 1 : 0))); return s; });
