        cover += c; if (days) parts.push(`${people[i].name} ${c} of the ${days} days ${people[i].name} is the only aide free`);
      }
      if (need > cover) {
        const floors = aides.filter((i) => bnd[i].lo > 0).map((i) => `${people[i].name} ${bnd[i].lo}`).join(', ');
        return `rule 4 makes the aides work at least ${need} shifts (${floors}), but only one aide fits a day, and leave and rule 3 let the aides cover at most ${cover} days: ${[`${shared} days when two or more aides are free`, ...parts].join(', ')}`;
      }
    }
    return null;
  };
