  if (coupled) { const why = aideCover(); if (why) return why; }
  if (coupled) for (let i = 0; i < k; i++) { // forced days alone already over a cap
    const name = people[i].name;
    if (fPre[i][n] > bnd[i].hi) return `${name} must work ${fPre[i][n]} days (on each, ${name} is the only nurse free or one of only two people free), but rule 4 caps ${name} at ${bnd[i].hi}`;
    if (fWkPre[i][n] > bnd[i].whi) return `${name} must work ${fWkPre[i][n]} weekend days (on each, ${name} is the only nurse free or one of only two people free), but rule 5 caps ${name} at ${bnd[i].whi}`;
  }
  for (let L = 1; L <= n; L++) {
    for (let a = 0; a + L <= n; a++) {
      const b = a + L, W = wkPre[b] - wkPre[a];
      let max = 0, nurseMax = 0, aideMax = 0, min = 0, aideMin = 0, wmax = 0, wmin = 0, wNurseMax = 0, wAideMin = 0;
      const who = []; // pass 2: where forced days actually tighten someone's term, in words
      for (let i = 0; i < k; i++) {
        const x = bnd[i], nurse = people[i].role === 'nurse';
