        const fWkIn = coupled ? fWkPre[i][b] - fWkPre[i][a] : 0, fWkOut = coupled ? fWkPre[i][n] - fWkIn : 0;
        const inside = Math.min(x.hi - fOut, most[i][a].row[L]);
        const outside = most[i][0].row[a] + most[i][b].row[n - b];
        const need = Math.max(0, x.lo - outside, fIn);
        const wIn = Math.max(0, Math.min(x.whi - fWkOut, wkFree[i][b] - wkFree[i][a], inside - (fIn - fWkIn)));
        const wOut = (wkFree[i][a] - wkFree[i][0]) + (wkFree[i][n] - wkFree[i][b]);
