// people.mjs — load and validate the team file.
import { readFileSync } from 'node:fs';

const isDate = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) &&
  !Number.isNaN(Date.parse(`${s}T00:00:00Z`)) && new Date(`${s}T00:00:00Z`).toISOString().slice(0, 10) === s;

// POLICY.md: "Every person has an fte (1 = full time) and a list of leave dates."
// Missing fte is an error, not a guess; fte above 1 is rejected (the policy calls 1 full time).
export function validatePeople(raw) {
  if (!Array.isArray(raw) || raw.length === 0) throw new Error('the team file must be a non-empty list of people');
  const seen = new Set();
  return raw.map((p) => {
    if (!p || typeof p.name !== 'string' || !p.name || !['nurse', 'aide'].includes(p.role)) throw new Error(`bad person: ${JSON.stringify(p)}`);
    if (seen.has(p.name)) throw new Error(`duplicate name: ${p.name}`);
    seen.add(p.name);
    if (p.fte === undefined || p.fte === null) throw new Error(`missing fte for ${p.name}`);
    const fte = Number(p.fte);
    if (!Number.isFinite(fte) || fte < 0 || fte > 1) throw new Error(`fte for ${p.name} must be between 0 and 1, got ${p.fte}`);
    const leave = p.leave ?? [];
    if (!Array.isArray(leave) || !leave.every(isDate)) throw new Error(`leave for ${p.name} must be a list of YYYY-MM-DD dates`);
    return { ...p, fte, leave: new Set(leave) };
  });
}

export function loadPeople(path) {
  return validatePeople(JSON.parse(readFileSync(path, 'utf8')));
}

