// policy.mjs — POLICY.md as code: the shares (rules 4 and 5) and a checker for all five rules.
// The checker is independent of how a rota was built; the tests judge every rota with it.
import { days, isWeekend } from './calendar.mjs';

export const MAX_RUN = 5;      // rule 3
export const TOTAL_SLACK = 2;  // rule 4
export const WEEKEND_SLACK = 1.5; // rule 5
export const EPS = 1e-9;       // float noise only; never widens a rule in practice

// Rule 4/5 shares. weight = fte × (days in the period not on leave) / DAYS.
export function shares(people, start, n) {
  const ds = days(start, n);
  const nWeekend = ds.filter(isWeekend).length;
  const weights = people.map((p) => (p.fte * ds.filter((d) => !p.leave.has(d)).length) / n);
  const sum = weights.reduce((a, b) => a + b, 0);
  return people.map((p, i) => ({
    name: p.name,
    weight: weights[i],
    total: sum > 0 ? (2 * n * weights[i]) / sum : 0,
    weekend: sum > 0 ? (2 * nWeekend * weights[i]) / sum : 0,
  }));
}

// Integer bounds each person must land in, from the shares.
export function bounds(share) {
  return {
    lo: Math.max(0, Math.ceil(share.total - TOTAL_SLACK - EPS)),
    hi: Math.floor(share.total + TOTAL_SLACK + EPS),
    wlo: Math.max(0, Math.ceil(share.weekend - WEEKEND_SLACK - EPS)),
    whi: Math.floor(share.weekend + WEEKEND_SLACK + EPS),
  };
}

// Every breach of every rule, as readable strings. [] means the rota is lawful.
export function checkRota(people, start, n, rota) {
  const out = [];
  const ds = days(start, n);
  const byName = new Map(people.map((p) => [p.name, p]));
  const keys = Object.keys(rota);
  if (keys.length !== n || ds.some((d) => !rota[d])) out.push(`rota covers ${keys.length} dates, period has ${n}`);
  const total = new Map(people.map((p) => [p.name, 0]));
  const wk = new Map(people.map((p) => [p.name, 0]));
  const run = new Map(people.map((p) => [p.name, 0]));
  for (const d of ds) {
    const on = rota[d] || [];
    // rule 1
    if (on.length !== 2 || new Set(on).size !== 2) out.push(`rule 1: ${d} has ${JSON.stringify(on)}, not two different people`);
    if (on.some((x) => !byName.has(x))) out.push(`rule 1: ${d} names someone not on the team`);
    if (!on.some((x) => byName.get(x)?.role === 'nurse')) out.push(`rule 1: ${d} has no nurse`);
    for (const x of on) {
      const p = byName.get(x);
      if (!p) continue;
      if (p.leave.has(d)) out.push(`rule 2: ${x} works ${d}, a leave date`); // rule 2
      total.set(x, total.get(x) + 1);
      if (isWeekend(d)) wk.set(x, wk.get(x) + 1);
    }
    for (const p of people) {
      const r = on.includes(p.name) ? run.get(p.name) + 1 : 0;
      run.set(p.name, r);
      if (r === MAX_RUN + 1) out.push(`rule 3: ${p.name} works more than ${MAX_RUN} days in a row, ending ${d}`);
    }
  }
  for (const s of shares(people, start, n)) {
    const t = total.get(s.name), w = wk.get(s.name);
    if (Math.abs(t - s.total) > TOTAL_SLACK + EPS) out.push(`rule 4: ${s.name} has ${t} shifts, share ${s.total.toFixed(2)}`);
    if (Math.abs(w - s.weekend) > WEEKEND_SLACK + EPS) out.push(`rule 5: ${s.name} has ${w} weekend shifts, share ${s.weekend.toFixed(2)}`);
  }
  return out;
}

// Tallies, for people reading a rota (and for the tests).
export function tally(people, rota) {
  const t = Object.fromEntries(people.map((p) => [p.name, { total: 0, weekend: 0 }]));
  for (const [d, on] of Object.entries(rota)) for (const x of on) { t[x].total++; if (isWeekend(d)) t[x].weekend++; }
  return t;
}

